<?php
require_once __DIR__ . '/includes/auth.php'; require_once __DIR__ . '/includes/functions.php';
$pdo=aep_database();$id=(int)($_GET['id']??0);$stmt=$pdo->prepare('SELECT * FROM clients WHERE id=?');$stmt->execute([$id]);$client=$stmt->fetch();if(!$client){http_response_code(404);exit('Client not found.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){aep_validate_csrf();$name=aep_post_string('name',160);$email=aep_post_string('email',160);if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))){$error='Enter a client name and a valid email address if provided.';}else{$pdo->prepare('UPDATE clients SET name=?,email=?,phone=?,address=?,updated_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$name,$email,aep_post_string('phone',60),aep_post_string('address',1000),$id]);aep_log_activity($pdo,'Clients','Updated client '.$name,$id);header('Location: client_view.php?id='.$id);exit;}}
$pageTitle='Edit Client | AEP';$activeNav='clients';require __DIR__.'/includes/header.php';?>
<div class="card" style="max-width:820px;margin:auto"><h1>Edit Client</h1><?php if($error):?><p style="color:#b42318"><?php echo aep_h($error);?></p><?php endif;?><form method="post" class="grid grid-2" style="margin-top:18px"><?php echo aep_csrf_field();?><div><label>Client name *</label><input required name="name" value="<?php echo aep_h($_POST['name']??$client['name']);?>"></div><div><label>Email</label><input type="email" name="email" value="<?php echo aep_h($_POST['email']??$client['email']);?>"></div><div><label>Phone</label><input name="phone" value="<?php echo aep_h($_POST['phone']??$client['phone']);?>"></div><div><label>Address</label><textarea name="address"><?php echo aep_h($_POST['address']??$client['address']);?></textarea></div><div class="actions"><button class="btn">Save changes</button><a class="btn secondary" href="client_view.php?id=<?php echo $id;?>">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';?>
